            "text": "{\"findings\":[{\"tipo\":\"GC\",\"causa_raiz\":\"Concatenação contínua de strings em loop (s += i.ToString()) e alocação desnecessária de grandes arrays (new object[10000]) dentro do método Update(), gerando mais de 10 MB de lixo por frame e provocando pausas de Coleta de Lixo (GC.Collect) de mais de 21ms.\",\"codigo_refatorado\":\"using System.Text; using UnityEngine; namespace PerformanceAdvisor.StressTest { public class StressTestScene : MonoBehaviour { public bool stressGc = false; public bool stressCpu = false; public bool stressDraw = false; public GameObject testPrefab; [Range(1, 20)] public float spawnRadius = 10f; [Range(1, 50)] public int cubesPerFrame = 1; public bool useUniqueMaterials = false; [Range(1, 512)] public int cpuScansPerFrame = 1; public int emptyObjects = 0; public int gcConcatIterations = 1000; public int gcArrayAllocs = 0; public int overdrawLayers = 0; public Material overdrawMaterial; [Range(0, 2000)] public int prepopulateCount = 0; private StringBuilder _cachedStringBuilder; private MaterialPropertyBlock _propBlock; private static readonly int ColorProp = Shader.PropertyToID(\\\"_Color\\\"); private void Awake() { _cachedStringBuilder = new StringBuilder(4096); _propBlock = new MaterialPropertyBlock(); } private void Start() { if (prepopulateCount \u003e 0 && testPrefab != null) { for (int i = 0; i \u003c prepopulateCount; i++) { SpawnOne(); } } for (int i = 0; i \u003c emptyObjects; i++) { new GameObject(\\\"Empty_\\\" + i); } if (overdrawLayers \u003e 0 && overdrawMaterial != null) { BuildOverdrawLayers(); } } private void BuildOverdrawLayers() { Camera cam = Camera.main; if (cam == null) return; float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad; for (int i = 0; i \u003c overdrawLayers; i++) { float d = cam.nearClipPlane + 0.05f + i * 0.001f; float h = 2f * d * Mathf.Tan(halfFov) * 1.1f; var quad = GameObject.CreatePrimitive(PrimitiveType.Quad); Destroy(quad.GetComponent\u003cCollider\u003e()); quad.name = \\\"Overdraw_\\\" + i; quad.transform.SetParent(cam.transform, false); quad.transform.localPosition = new Vector3(0f, 0f, d); quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f); quad.GetComponent\u003cRenderer\u003e().sharedMaterial = overdrawMaterial; } } private void Update() { if (stressGc) { _cachedStringBuilder.Clear(); for (int i = 0; i \u003c gcConcatIterations; i++) { _cachedStringBuilder.Append(i); } } if (stressDraw && testPrefab != null) { int n = Mathf.Max(1, cubesPerFrame); for (int i = 0; i \u003c n; i++) { SpawnOne(); } } } private void SpawnOne() { var clone = Instantiate(testPrefab, Random.insideUnitSphere * spawnRadius, Quaternion.identity); if (useUniqueMaterials && clone.TryGetComponent\u003cRenderer\u003e(out var rend)) { rend.GetPropertyBlock(_propBlock); _propBlock.SetColor(ColorProp, new Color(Random.value, Random.value, Random.value)); rend.SetPropertyBlock(_propBlock); } } } }\",\"explicacao_didatica\":\"Em C#, strings são imutáveis; concatenar strings dentro de um laço de repetição cria centenas de objetos descartáveis na memória que sobrecarregam o Garbage Collector (GC), gerando 'engasgos' (stutters) visíveis na taxa de quadros. Substituir a concatenação por StringBuilder reaproveitável e remover alocações de arrays elimina o desperdício de memória em tempo de execução.\"},{\"tipo\":\"CPU\",\"causa_raiz\":\"Chamadas repetidas a GameObject.FindObjectsOfType no método Update(). Este método faz uma busca exaustiva por todos os objetos carregados na cena e aloca um novo array no heap a cada chamada, elevando o tempo de processamento da CPU para 122ms por frame.\",\"codigo_refatorado\":\"using System.Collections.Generic; using UnityEngine; namespace PerformanceAdvisor.StressTest { public class CachedEntityRegistry : MonoBehaviour { private static readonly List\u003cGameObject\u003e ActiveEntities = new List\u003cGameObject\u003e(); public static IReadOnlyList\u003cGameObject\u003e AllEntities =\u003e ActiveEntities; private void OnEnable() =\u003e ActiveEntities.Add(gameObject); private void OnDisable() =\u003e ActiveEntities.Remove(gameObject); } }\",\"explicacao_didatica\":\"Buscar objetos em tempo real usando FindObjectsOfType obriga o processador a verificar toda a árvore da cena várias vezes a cada segundo. O padrão correto é registrar objetos automaticamente em uma lista estática durante o OnEnable/Awake e desregistrá-los no OnDisable, garantindo acesso instantâneo sem custo de varredura.\"}],\"dicas_level_design\":null}",
